// Database connection + migrations.
//
// Migrations (server/db/migrations, generated by drizzle-kit from schema.js) run on every start,
// inside a Postgres advisory lock, so two containers starting at once (a rolling deploy, or
// several replicas) never apply them twice. If any are pending and BACKUP_DIR is set, a pg_dump
// of the whole database is written first, so a bad migration can always be undone.
import pg from 'pg'
import path from 'node:path'
import fs from 'node:fs'
import { spawn } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { drizzle } from 'drizzle-orm/node-postgres'
import { migrate } from 'drizzle-orm/node-postgres/migrator'
import { readMigrationFiles } from 'drizzle-orm/migrator'
import * as schema from './schema.js'

export const MIGRATIONS_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'migrations')
const LOCK_ID = 7_361_204_001 // arbitrary, constant: "life-console migrations"

export function connect(databaseUrl, { max = 10 } = {}) {
  const pool = new pg.Pool({ connectionString: databaseUrl, max })
  pool.on('error', (err) => console.error(new Date().toISOString(), '[db] idle client error', err.message))
  const db = drizzle(pool, { schema })
  return { pool, db }
}

/** Migrations in the folder that this database hasn't applied yet. */
async function pending(client) {
  const files = readMigrationFiles({ migrationsFolder: MIGRATIONS_DIR })
  const { rows: [t] } = await client.query(`select to_regclass('drizzle.__drizzle_migrations') as t`)
  if (!t.t) return files
  const { rows: [last] } = await client.query('select max(created_at)::bigint as at from drizzle.__drizzle_migrations')
  const at = Number(last.at) || 0
  return files.filter((m) => m.folderMillis > at)
}

/** pg_dump -Fc of the whole database into dir; resolves to the file path. */
export function dumpDatabase(databaseUrl, dir, label = 'backup') {
  fs.mkdirSync(dir, { recursive: true })
  const file = path.join(dir, `${label}-${new Date().toISOString().replace(/[:.]/g, '-')}.dump`)
  return new Promise((resolve, reject) => {
    const p = spawn('pg_dump', ['--format=custom', '--no-owner', `--file=${file}`, `--dbname=${databaseUrl}`], { stdio: ['ignore', 'inherit', 'inherit'] })
    p.on('error', reject)
    p.on('exit', (code) => (code === 0 ? resolve(file) : reject(new Error(`pg_dump exited with ${code}`))))
  })
}

export async function runMigrations(pool, { databaseUrl, backupDir, log = console.log } = {}) {
  const client = await pool.connect()
  try {
    await client.query('select pg_advisory_lock($1)', [LOCK_ID])
    const todo = await pending(client)
    if (!todo.length) { log('[db] schema up to date'); return 0 }
    const { rows: [{ n }] } = await client.query(`select count(*)::int as n from information_schema.tables where table_schema = 'public'`)
    if (backupDir && n > 0) {
      const file = await dumpDatabase(databaseUrl, backupDir, 'pre-migrate')
      log(`[db] backup before migrating: ${file}`)
    }
    await migrate(drizzle(client), { migrationsFolder: MIGRATIONS_DIR }) // one transaction for all pending steps
    log(`[db] applied ${todo.length} migration(s)`)
    return todo.length
  } finally {
    await client.query('select pg_advisory_unlock($1)', [LOCK_ID]).catch(() => {})
    client.release()
  }
}
